// Riff's types: generated by .github/scripts/riff-types.js from the REST schemas, the track schema,
// the hook docblocks, the window.riff docblocks and Views::all(). Do not edit; run npm run types.

// ---- The track.
// One shape for a track: the REST field on media, the routes, the block markup and the player all use it. Riff\Tracks::schema(), version 1.

export interface Track {
	/** The attachment ID, or "url:" and a hash for a file outside the Media Library. */
	id: string;
	src: string;
	type: "audio" | "video";
	title: string;
	artist: string;
	album: string;
	/** The year from the file's tags, or 0. */
	year: number;
	/** Which disc of a set the track is on, from the file's disc number tag (1 for "1/2"), or 0 when the tags do not say. */
	disc: number;
	/** Seconds, 0 when unknown. */
	duration: number;
	/** The language of the title and artist, as a lang attribute takes it, from the file's tags; empty when the file does not say. */
	lang: string;
	/** The container, lower case, as WordPress read it from the file: mp3, flac, m4a. Empty when unknown. */
	format: string;
	/** Kilobits per second, 0 when unknown. */
	bitrate: number;
	/** Whether the encoding is lossless. */
	lossless: boolean;
	/** Bits per sample, as WordPress read it from the file; 0 when the format does not say, as MP3 does not. */
	bits: number;
	/** Samples per second, 0 when unknown. */
	rate: number;
	/** The track's loudness over time as digits 0 to 9, one per sample, when something has measured it; the drawn cover puts it in the groove. Empty otherwise. */
	levels: string;
	/** Artwork, smallest first. */
	art: {
		src: string;
		sizes: string;
		/** What the picture shows, for a screen reader: the image's alt text, or the album and artist a drawn cover names. */
		alt: string;
	}[];
	/** Text tracks for a video: the WebVTT file its Captions field names, or the tracks its video block carries. */
	captions: {
		src: string;
		label: string;
		srclang: string;
		kind: "captions" | "subtitles" | "descriptions";
	}[];
	video: {
		src: string;
		poster: string;
		captions: {
			src: string;
			label: string;
			srclang: string;
			kind: "captions" | "subtitles" | "descriptions";
		}[];
	} | null;
	post: {
		id: number;
		title: string;
		url: string;
		/** Whether the post is one visitors can't see, unpublished or behind a password. Only ever true for someone signed in who may see it. */
		private: boolean;
	} | null;
	/** The rights the artist set on the track or its album, from riff_rights; null while nothing is set. */
	rights: {
		holder: string;
		/** The year for the ℗ line, or 0. */
		year: number;
		license: string;
		/** The licence's deed, or empty for all rights reserved. */
		license_url: string;
		license_label: string;
		isrc: string;
		/** Whether the uploader stated they own or control the rights. */
		attested: boolean;
	} | null;
	/** Whether the current visitor may download the file, from riff_may_download. */
	downloads: boolean;
	/** Links a host adds to the track's info, from riff_item_links: a report link, say. Empty by default. */
	links: {
		label: string;
		url: string;
	}[];
	/** Whether the current visitor may not play the track, as riff_can_play decided. A locked track has no src. */
	locked: boolean;
	/** Where a locked track sends the visitor to unlock it, from riff_unlock_url. Empty otherwise. */
	unlock: string;
	/** Why a locked track is locked, for the listener, from riff_may_play: "No longer available" for one past its availability. Empty otherwise. */
	reason: string;
}

/** The track schema's version, Riff\\Tracks::SCHEMA_VERSION. */
export type TrackSchemaVersion = 1;

// ---- REST responses.
// What each riff/v1 route answers, by the title of its schema.

export interface LibraryResponse {
	items: {
		/** Post ID. */
		id: number;
		/** Post title. */
		title: string;
		/** Permalink. */
		url: string;
		/** The artist every track shares, or empty. */
		artist: string;
		/** Artwork, smallest first. */
		art: {
			src: string;
			sizes: string;
		}[];
		/** Number of tracks. */
		count: number;
		/** A one-line byline for the post, written by a feature that knows how to say it in the language. */
		meta: string;
		/** Total length in seconds, 0 when unknown. */
		duration: number;
	}[];
	page: number;
	pages: number;
	total: number;
}

export interface LibrarySummaryResponse {
	/** Audio files in the Media Library. */
	tracks: number;
	/** Albums, by the files' tags. */
	albums: number;
	/** Artists, by the files' tags. */
	artists: number;
	/** Published posts with music. */
	posts: number;
	/** Space taken, in bytes: by the audio files, and by every upload. */
	bytes: {
		audio: number;
		uploads: number;
	};
	/** The most the site may upload, in bytes, where its network sets a limit; null for none. */
	quota: number | null;
}

export interface LibraryPostResponse {
	/** Post ID. */
	id: number;
	/** Post title. */
	title: string;
	/** Permalink. */
	url: string;
	/** The artist every track shares, or empty. */
	artist: string;
	/** Artwork, smallest first. */
	art: {
		src: string;
		sizes: string;
	}[];
	/** Number of tracks. */
	count: number;
	/** A one-line byline for the post, written by a feature that knows how to say it in the language. */
	meta: string;
	/** Total length in seconds, 0 when unknown. */
	duration: number;
	/** The tracks, in order, as the player reads them. */
	tracks: Track[];
	/** How the tracks are pressed: the format, 12 or 7, and its sides, each with the tracks it holds. */
	pressing: Record<string, unknown>;
	/** The media blocks rendered as the post renders them. */
	html: string;
}

export interface ImportResponse {
	/** The zip's attachment ID. */
	attachment: number;
	/** When the import starts, as a Unix time. Its album posts are private, by the zip's uploader, with each track Protected, unless the site says otherwise; the zip is private until then, and deleted once it is unpacked. */
	queued: number;
}

/** A post's blocks as a tree, parsed by WordPress's own block parser, with the tracks Riff's blocks play resolved in place. */
export interface PostBlocksResponse {
	/** Post ID. */
	id: number;
	/** Post type. */
	type: string;
	/** Post title, as plain text. */
	title: string;
	/** Permalink. */
	url: string;
	/** When the post last changed, in UTC. */
	modified: string;
	/** The post's blocks, in order. HTML between blocks that is only white space is left out. */
	blocks: Block[];
}

export interface Block {
	/** The block's name, such as core/paragraph or core/audio; null for HTML outside any block, as a classic post holds. */
	blockName: string | null;
	/** The attributes saved in the block's comment. Those a block keeps in its markup, such as a paragraph's text, are in innerHTML instead. */
	attrs: Record<string, unknown>;
	/** The blocks inside this one, in order, each in this same shape. */
	innerBlocks: Block[];
	/** The block's own markup, with its inner blocks left out. */
	innerHTML: string;
	/** The same markup in pieces, with null where each inner block goes, in order. */
	innerContent: Array<string | null>;
	/** On an audio, video or playlist-track block only: the track it plays, in the track shape, or null when there is no file to play. */
	track?: Track | null;
}

/** Tracks from the Media Library, by title, or one album in its order, or one artist; searchable by title, artist and album. A visitor sees every track except those uploaded to an unpublished or password-protected post; someone who can upload files sees them all. */
export interface TracksResponse {
	/** Tracks, in the shape of the track schema. */
	items: Track[];
	page: number;
	pages: number;
	total: number;
	/** Where this page ended, to pass as after for the next; empty when this is the last, or for an album or include. */
	next: string;
}

/** Albums with at least one track the requester can see, by name, each with its artist, artwork and track count. */
export interface AlbumsResponse {
	items: {
		/** Term ID. */
		id: number;
		name: string;
		/** Tracks the requester can see. */
		count: number;
		/** The album's artist, or empty. */
		artist: string;
		/** The album's first track's artwork as the player shows it, as { src, sizes }. */
		art: unknown[];
	}[];
	page: number;
	pages: number;
	total: number;
}

/** Artists with at least one track the requester can see, by name, each with a track count. */
export interface ArtistsResponse {
	items: {
		/** Term ID. */
		id: number;
		name: string;
		/** Tracks the requester can see. */
		count: number;
	}[];
	page: number;
	pages: number;
	total: number;
}

/** The signed-in user's likes, newest first. Kept as the riff_likes user option, one list per site. */
export interface LikesResponse {
	items: {
		kind: "track" | "album" | "artist";
		id: number;
		/** When it was liked, in milliseconds since the epoch. */
		at: number;
	}[];
}

/** The tracks the signed-in user played, newest first, at most 30. Kept as the riff_history user option, one list per site. */
export interface HistoryResponse {
	items: Array<Track & {
		/** When it was played, in milliseconds since the epoch. */
		played: number;
	}>;
}

/** A user's playlists, the most recently changed first. Each is a private riff_playlist post holding a core Playlist block. */
export interface PlaylistsResponse {
	items: {
		id: number;
		title: string;
		/** How many tracks it holds. */
		count: number;
		/** Up to four covers from its first tracks, for a mosaic. */
		covers: string[];
		/** When it last changed. */
		modified: string;
	}[];
}

export interface PlaylistResponse {
	id: number;
	title: string;
	/** How many tracks it holds. */
	count: number;
	/** Up to four covers from its first tracks, for a mosaic. */
	covers: string[];
	/** When it last changed. */
	modified: string;
	/** Every track's ID, in order, including any the requester cannot see. */
	ids: number[];
	/** The tracks the requester can see, in the track shape, in order. */
	tracks: Array<Track & {
		/** The track's place in the playlist, from 0. */
		index: number;
	}>;
}

/** An album, as riff/v1/albums lists it. */
export type Album = AlbumsResponse['items'][number];

/** An artist, as riff/v1/artists lists it. */
export type Artist = ArtistsResponse['items'][number];

/** A listener's playlist, as riff/v1/users/{user}/playlists/{id} answers. */
export type Playlist = PlaylistResponse;

/** A post with tracks, as riff/v1/library lists it. */
export type LibraryItem = LibraryResponse['items'][number];

/** What Riff adds to each item of the attachment REST route (wp/v2/media). */
export interface AttachmentFields {
	/** The file as a track the player reads; null for files that are not audio or video. */
	riff_track: Track | null;
}

// ---- REST routes.
// Every route, by method and address, with what it takes and what it answers. The parameters in the address are part of params.

export interface Routes {
	"GET /riff/v1/library": {
		params: {
			/** Page of the library. */
			page?: number;
		};
		response: LibraryResponse;
	};
	"POST /riff/v1/library": {
		params: {
			/** The album's title. */
			title: string;
			/** Audio attachment IDs, in play order. */
			tracks: number[];
			/** Draft, for its author to look over first; published; or private. */
			status?: "draft" | "publish" | "private";
			/** An image attachment ID for the cover; the first track's artwork when not given. */
			artwork?: number;
		};
		response: LibraryResponse;
	};
	"GET /riff/v1/library/summary": {
		params: Record<string, never>;
		response: LibrarySummaryResponse;
	};
	"GET /riff/v1/library/{id}": {
		params: {
			/** Post ID. */
			id: number;
		};
		response: LibraryPostResponse;
	};
	"POST /riff/v1/imports": {
		params: {
			/** The zip's attachment ID, in the Media Library and attached to no post. */
			attachment: number;
		};
		response: ImportResponse;
	};
	/** A post's blocks as a tree, parsed by WordPress's own block parser, with the tracks Riff's blocks play resolved in place. */
	"GET /riff/v1/posts/{id}/blocks": {
		params: {
			/** Post ID. */
			id: number;
		};
		response: PostBlocksResponse;
	};
	/** Tracks from the Media Library, by title, or one album in its order, or one artist; searchable by title, artist and album. A visitor sees every track except those uploaded to an unpublished or password-protected post; someone who can upload files sees them all. */
	"GET /riff/v1/tracks": {
		params: {
			/** Words to look for, at least two characters: a track matches on its title, artist or album; an album or artist on its name. */
			search?: string;
			/** Only the tracks on this album, by term ID, in album order. */
			album?: number;
			/** Only the tracks by this artist, by term ID. */
			artist?: number;
			/** Only these, by ID; what the requester cannot see is still left out. */
			include?: number[];
			/** By title, the most recently added first, in the order include names them, or shuffled by seed. An album is in album order unless shuffled. */
			orderby?: "title" | "added" | "include" | "random";
			/** With orderby random, the shuffle: the same seed deals the same order, so its pages follow on without a track twice. */
			seed?: number;
			/** Page of results. */
			page?: number;
			/** Where the last page ended, as its next said: the page after it, which stays fast however deep into the library it is. By title or newest first, and not with album or include. */
			after?: string;
			/** Tracks per page. */
			per_page?: number;
		};
		response: TracksResponse;
	};
	/** Albums with at least one track the requester can see, by name, each with its artist, artwork and track count. */
	"GET /riff/v1/albums": {
		params: {
			/** Words to look for, at least two characters: a track matches on its title, artist or album; an album or artist on its name. */
			search?: string;
			/** Only the albums with a track by this artist, by term ID. */
			artist?: number;
			/** Only these, by ID; what the requester cannot see is still left out. */
			include?: number[];
			/** By name, or the most recently added first. */
			orderby?: "name" | "added";
			/** Page of results. */
			page?: number;
		};
		response: AlbumsResponse;
	};
	/** Artists with at least one track the requester can see, by name, each with a track count. */
	"GET /riff/v1/artists": {
		params: {
			/** Words to look for, at least two characters: a track matches on its title, artist or album; an album or artist on its name. */
			search?: string;
			/** Only these, by ID; what the requester cannot see is still left out. */
			include?: number[];
			/** Page of results. */
			page?: number;
		};
		response: ArtistsResponse;
	};
	/** The signed-in user's likes, newest first. Kept as the riff_likes user option, one list per site. */
	"GET /riff/v1/users/{user}/likes": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
		};
		response: LikesResponse;
	};
	/** The signed-in user's likes, newest first. Kept as the riff_likes user option, one list per site. */
	"POST /riff/v1/users/{user}/likes": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** Likes to add: a kind and an ID each, and when it was liked. */
			items: {
				/** What is liked: track, album or artist. */
				kind: "track" | "album" | "artist";
				/** The audio attachment's ID for a track, or the term ID for an album or artist. */
				id: number;
				/** When it was liked, in milliseconds since the epoch. Now when left out. */
				at: number;
			}[];
		};
		response: LikesResponse;
	};
	/** The signed-in user's likes, newest first. Kept as the riff_likes user option, one list per site. */
	"DELETE /riff/v1/users/{user}/likes/{kind}/{id}": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** What was liked: track, album or artist. */
			kind: "track" | "album" | "artist";
			/** Its ID. */
			id: number;
		};
		response: LikesResponse;
	};
	/** The tracks the signed-in user played, newest first, at most 30. Kept as the riff_history user option, one list per site. */
	"GET /riff/v1/users/{user}/history": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
		};
		response: HistoryResponse;
	};
	/** The tracks the signed-in user played, newest first, at most 30. Kept as the riff_history user option, one list per site. */
	"POST /riff/v1/users/{user}/history": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** Plays to add: a track's ID each, and when it was played. */
			items: {
				/** The audio attachment's ID. */
				id: number;
				/** When it was played, in milliseconds since the epoch. Now when left out. */
				played: number;
				/** The post it was played from, for Jump back in, or 0. */
				post: number;
			}[];
		};
		response: HistoryResponse;
	};
	/** The tracks the signed-in user played, newest first, at most 30. Kept as the riff_history user option, one list per site. */
	"DELETE /riff/v1/users/{user}/history": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
		};
		response: HistoryResponse;
	};
	/** A user's playlists, the most recently changed first. Each is a private riff_playlist post holding a core Playlist block. */
	"GET /riff/v1/users/{user}/playlists": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
		};
		response: PlaylistsResponse;
	};
	/** A user's playlists, the most recently changed first. Each is a private riff_playlist post holding a core Playlist block. */
	"POST /riff/v1/users/{user}/playlists": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** The playlist's name. */
			title: string;
			/** Tracks, by their audio attachments' IDs, in order. */
			tracks?: number[];
		};
		response: PlaylistsResponse;
	};
	"GET /riff/v1/users/{user}/playlists/{id}": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** The playlist's post ID. */
			id: number;
		};
		response: PlaylistResponse;
	};
	"POST /riff/v1/users/{user}/playlists/{id}": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** The playlist's post ID. */
			id: number;
			/** The playlist's name. */
			title?: string;
			/** Tracks, by their audio attachments' IDs, in order. */
			tracks?: number[];
		};
		response: PlaylistResponse;
	};
	"DELETE /riff/v1/users/{user}/playlists/{id}": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** The playlist's post ID. */
			id: number;
		};
		response: PlaylistResponse;
	};
	"POST /riff/v1/users/{user}/playlists/{id}/tracks": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** The playlist's post ID. */
			id: number;
			/** Tracks, by their audio attachments' IDs, in order. */
			tracks: number[];
		};
		response: PlaylistResponse;
	};
	"DELETE /riff/v1/users/{user}/playlists/{id}/tracks/{index}": {
		params: {
			/** Whose: me for the signed-in user, or a user ID, for someone who may edit that user. */
			user: string;
			/** The playlist's post ID. */
			id: number;
			/** The track's place in the playlist, from 0. */
			index: number;
		};
		response: PlaylistResponse;
	};
}

/** A route, as `METHOD /namespace/address`. */
export type Route = keyof Routes;

// ---- window.riff.
// The player's public api, handed to riff.ready and kept on window.riff once the player starts.

export interface RiffApi {
	/**
	 * The version of this api: 1.
	 *
	 * @since 4.0.0
	 */
	readonly version: number;
	/**
	 * Makes `tracks` the queue and plays the one at `index`.
	 *
	 * The tracks go through the `riff.queue` and `riff.track` filters first.
	 *
	 * @since 4.0.0
	 */
	play(tracks: Track[], index?: number, options?: {
		/** `true` or `false` sets shuffle before playing. */
		shuffle?: boolean;
	}): void;
	/**
	 * Plays or pauses.
	 *
	 * @since 4.0.0
	 */
	toggle(): void;
	/**
	 * Skips to the next track.
	 *
	 * @since 4.0.0
	 */
	next(): void;
	/**
	 * Goes back a track, or to the start of this one.
	 *
	 * @since 4.0.0
	 */
	prev(): void;
	/**
	 * Moves the current track to a time.
	 *
	 * @since 4.0.0
	 */
	seek(seconds: number): void;
	/**
	 * Opens Now Playing, on a view of it when one is named.
	 *
	 * @since 4.0.0
	 */
	open(view?: string): void;
	/**
	 * Closes Now Playing.
	 *
	 * @since 4.0.0
	 */
	close(): void;
	/**
	 * The track playing.
	 *
	 * @since 4.0.0
	 */
	current(): Track | null;
	/**
	 * The queue in play order.
	 *
	 * @since 4.0.0
	 */
	queue(): Track[];
	/**
	 * Whether something is playing.
	 *
	 * The same answer the Pause button gives. On the turntable the music starts and stops as a record does, so this is true from the press of Play, while the needle is still being cued, and false from the press of Pause, while the music winds down.
	 *
	 * @since 4.0.0
	 */
	playing(): boolean;
	/**
	 * Where the track is.
	 *
	 * @since 4.32.0
	 */
	time(): number;
	/**
	 * The music as Web Audio hears it, for a plugin to read: connect an AnalyserNode of your own to this one, and never to anything that changes the sound. It is null where the music doesn't pass through Web Audio, so nothing should be drawn: before the first play, on an iPhone, for a file from another origin that doesn't share over CORS, and while a video plays.
	 *
	 * @since 6.3.0
	 */
	analyser(): AnalyserNode | null;
	/**
	 * How fast the music plays, with its pitch kept where the browser can keep it (`preservesPitch`): slower to learn a part, faster to skim. Given a rate, from 0.5 to 2, it sets it, and the speed holds for every track until it is set again. On the turntable it is multiplied by the deck's own speed and pitch.
	 *
	 * @since 5.8.0
	 */
	speed(rate?: number): number;
	/**
	 * Plays another file in place of the track's own, for now: the same music made another way, such as its instrumental to sing over. It carries on from the same second, at the same speed, playing or paused as it was, and it is still the same track to the listener and to every script: no `riff.track` fires, and `window.riff.time()` keeps the clock. Given null it goes back to the track's own file the same way. The track's own comes back by itself when the track changes, when the player is dismissed, and when the other file can't be played. Not while a video plays: a song's file only. The file must be one the listener may have; a protected file's address is the site's own, which answers for whoever may play it.
	 *
	 * @since 6.11.0
	 */
	source(src: string | null): boolean;
	/**
	 * Gives a view what it does as it opens, or adds one the server didn't register. A view is opened from its button in the bar, and on a phone from its chip in Now Playing (the album, the stage, has no button: the bar itself opens it): a screen of Now Playing, which takes the whole screen above the bar, or a panel beside the page. Register a view on the server with `riff_register_view()`, so the page has it before any script; this is for what only the browser knows. Riff's own are the album (`album`, order 26; the cover, or the turntable where Now Playing is landscape), About (`about`, a panel, 36), Up next (`queue`, a panel, 40) and Together (`together`, a panel, 45); Riff Lyrics registers Lyrics (`lyrics`, 30), Riff Sing Sing (`sing`, 32) and Riff Chords Chords (`chords`, 34). A view with nothing for a track says so with `shown`: its button and chip hide while that track plays, and if it is open when the track changes to one, a screen goes back to the one the listener came from, or to what Now Playing opens to, and a panel closes.
	 *
	 * @since 5.8.0
	 */
	view(id: string, view: {
		/** Its name: its heading, its button's and its chip's. Needed for one the server didn't register. */
		label?: string;
		/** Its button's icon, SVG markup from your own code, never from content. */
		icon?: string;
		/** Where its button sits among the bar's controls, lowest first. Default 50. */
		order?: number;
		/** `screen`, the default; `side` for a panel; or `sidebar` to be docked in the Listen app's sidebar under a row of its own, open beside whatever the listener browses, and a panel wherever there is no sidebar. */
		place?: string;
		/** Fills it as it opens and again as the track changes while it is open. The `riff.view` action says the same. */
		render?: (view: HTMLElement, track: Track | null) => void;
		/** Whether it has something for the track, so its button and chip show. Default always. */
		shown?: (track: Track | null) => boolean;
	}): () => void;
	/**
	 * Opens a view: a screen of Now Playing, a panel beside the page, or a sidebar view in the Listen app's sidebar (folded to its rail, the sidebar opens for it).
	 *
	 * @since 5.8.0
	 */
	openView(id: string): void;
	/**
	 * Closes a view: the one named, wherever it is, or with no id the panel that is open, or else Now Playing. Views docked in the sidebar close only by name, as several may be open there beside the rest.
	 *
	 * @since 5.8.0
	 */
	closeView(id?: string): void;
	/**
	 * Gives a control in the player's bar what it does, or adds one the server didn't register. Register a control on the server with `riff_register_control()`, so the page has it before any script; this is for what only the browser knows. Riff's own are Like (order 10), the badges (20), Play on another device (60) and the volume (70).
	 *
	 * @since 5.8.0
	 */
	control(id: string, control: {
		/** What it is called, for a screen reader and a pointer's tooltip; or a function of the track. Needed for one the server didn't register. */
		label?: string | ((track: Track | null) => string);
		/** Its icon, SVG markup from your own code, never from content. */
		icon?: string;
		/** Where it sits among the others, lowest first. Default 50. */
		order?: number;
		/** What a press does. */
		run?: (track: Track | null, button: HTMLElement) => void;
		/** One of the player's own actions instead of `run`, such as `shuffle` or `repeat`. */
		action?: string;
		/** Whether it is pressed, for a control that turns something on and off. */
		pressed?: (track: Track | null) => boolean;
		/** Whether it shows. Default always. */
		shown?: (track: Track | null) => boolean;
		/** Only on a wide screen; a phone's bar keeps to the track, Play and what it needs. */
		wide?: boolean;
		/** An element of your own in place of a button, which you keep up to date. */
		element?: () => HTMLElement;
	}): () => void;
	/**
	 * Gives a keyboard shortcut registered on the server with `riff_register_shortcut()` what it does. It follows Riff's own single-key shortcuts: it acts only while a track is loaded, never while the listener types in a field or holds Ctrl, Alt or Command (though a mark typed with AltGr counts where the browser reports AltGr, as `[` on a German keyboard), and only where those are on, for a signed-in listener who has not turned them off on their profile, unless the `riff.shortcuts` filter turns them off. A key the server didn't register does nothing, since the profile lists every key there is.
	 *
	 * @since 5.9.0
	 */
	shortcut(id: string, run: (track: Track, event: KeyboardEvent) => void): () => void;
	/**
	 * Listens to one of the player's actions, without `wp-hooks`.
	 *
	 * @since 4.0.0
	 */
	on<K extends keyof RiffEventDetails>(name: K, fn: (detail: RiffEventDetails[K], api: RiffApi) => void): () => void;
	/**
	 * Listens along with another listener on this site, as Listen along in the Together panel does: plays what they play, where they are in it, and keeps with them through their plays, pauses, skips and seeks, until a press of the listener's own. A link from `riff_together_along_url()` does this as the page opens. Where the browser won't start the music without a press, the listener is asked to press play, and that press joins.
	 *
	 * @since 6.15.0
	 */
	along(user: number): Promise<boolean>;
}

// ---- Actions and filters.
// Through wp.hooks: wp.hooks.addAction( name, namespace, callback ) and wp.hooks.addFilter( name, namespace, callback ), the callback typed here by name.

export interface RiffActions {
	/**
	 * Fires when a view of the Listen app shows: the first as the app starts, then each one in-page navigation brings, and again when one is drawn again in place. A plugin that added a view with the `riff_app_views` filter binds its script to what it drew here, or on the `riff:app_view` event, which bubbles to `document`.
	 *
	 * @since 6.4.0
	 */
	"riff.app_view": (detail: {
		/** Its slug: `home`, `albums`, `album`, `post` and the rest of Riff's, or the plugin's own. */
		view: string;
		/** The element the view is drawn in, `[data-riff-app-view]`; a plugin's is inside it, `[data-riff-app-panel="<slug>"]`. */
		panel: HTMLElement;
	}, api: RiffApi) => void;
	/**
	 * Fires when a track plays to its end, before the next one loads.
	 *
	 * @since 4.0.0
	 */
	"riff.ended": (detail: {
		/** The track that ended. */
		track: Track;
	}, api: RiffApi) => void;
	/**
	 * Fires when the track pauses.
	 *
	 * @since 4.0.0
	 */
	"riff.pause": (detail: {
		/** The track. */
		track: Track;
	}, api: RiffApi) => void;
	/**
	 * Fires when the track starts or resumes playing.
	 *
	 * @since 4.0.0
	 */
	"riff.play": (detail: {
		/** The track. */
		track: Track;
	}, api: RiffApi) => void;
	/**
	 * Fires when the queue changes while it plays: tracks added to play next or at the end, one moved or removed, or the queue cleared.
	 *
	 * @since 4.19.0
	 */
	"riff.queue": (detail: {
		/** `next`, `add`, `move`, `remove` or `clear`. */
		change: string;
		/** The queue in play order. */
		queue: Track[];
		/** The playing track's place in it. */
		index: number;
	}, api: RiffApi) => void;
	/**
	 * Fires once the player is set up, its state restored and `window.riff` available.
	 *
	 * @since 4.0.0
	 */
	"riff.ready": (detail: {
		/** The queue in play order. */
		queue: Track[];
		/** The track loaded, or null. */
		track: Track | null;
	}, api: RiffApi) => void;
	/**
	 * Fires as the track plays, a few times a second, and again after a seek.
	 *
	 * @since 4.32.0
	 */
	"riff.time": (detail: {
		/** The track. */
		track: Track;
		/** Seconds from its start. */
		time: number;
		/** Its length in seconds, or 0 until known. */
		duration: number;
	}, api: RiffApi) => void;
	/**
	 * Fires when a track is loaded, before it plays.
	 *
	 * @since 4.0.0
	 */
	"riff.track": (detail: {
		/** The track now loaded. */
		track: Track;
		/** Its position in the play order. */
		index: number;
		/** The queue in play order. */
		queue: Track[];
	}, api: RiffApi) => void;
	/**
	 * Fires when a view opens or closes, Riff's own included, and again for an open view when the track changes. A view's script fills it here, or in the `render` it was given.
	 *
	 * @since 5.8.0
	 */
	"riff.view": (detail: {
		/** The view's id. */
		id: string;
		/** Whether it is open now. */
		open: boolean;
		/** Its region: `[data-riff-view="<id>"]` for a screen of its own, `[data-riff-panel="<id>"]` for a panel and for a sidebar view, docked or not, and Now Playing itself for the album. */
		view: HTMLElement;
		/** The track playing. */
		track: Track | null;
		/** Closing, whether the panel is only put away, as beside the deck on its own, to open again by itself once that is left: what the view does, such as a sound of its own, may go on. Since 6.14.0. */
		away: boolean;
	}, api: RiffApi) => void;
}

export interface RiffFilters {
	/**
	 * Filters the items of the track menu, the … beside every row and every track in Up next.
	 *
	 * Return the items with yours added where they belong: the menu shows them in the order given. Riff's own are, in order, `next` (Play next), `add` (Add to queue), `like`, `playlist`, then in Up next `up`, `down` and `remove`, then `post` (Go to post), each only where it applies, with what Riff's own features add, such as Listen along, among them; find one by its `id` rather than its place. An item with neither `run` nor `href`, or with no `label`, is left out.
	 *
	 * @since 5.9.0
	 */
	"riff.menu": (items: Array<Record<string, unknown>>, track: Track, context: {
		/** `row`, a row on the page, or `queue`, a track in Up next. */
		where: string;
		/** For Up next, the track's place in the queue, from 0. */
		index: number;
	}) => Array<Record<string, unknown>>;
	/**
	 * Filters the tracks about to become the queue.
	 *
	 * Return a new array to add, drop or reorder tracks before any of them plays.
	 *
	 * @since 4.0.0
	 */
	"riff.queue": (tracks: Track[], index: number) => Track[];
	/**
	 * Filters whether the single-key shortcuts (Space, K, J, L and plugins' keys) act on a key press.
	 *
	 * Return `false` to turn them off, which WCAG 2.1.4 asks to be possible. It turns off the keys plugins register with `riff_register_shortcut()` too.
	 *
	 * @since 4.0.1
	 */
	"riff.shortcuts": (enabled: boolean, event: KeyboardEvent) => boolean;
	/**
	 * Filters one track as a queue is set, after `riff.queue`.
	 *
	 * @since 4.0.0
	 */
	"riff.track": (track: Track) => Track;
}

/** An action's name, such as riff.play. */
export type RiffAction = keyof RiffActions;

/** A filter's name, such as riff.queue. */
export type RiffFilter = keyof RiffFilters;

// ---- Events.
// Each action is also a riff:<name> CustomEvent with the same detail, dispatched on #riff, bubbling; riff:app_view on document. For pages without the WordPress scripts.

/** Each action's detail, by its name without the prefix, as window.riff.on() and the events hand it. */
export interface RiffEventDetails {
	app_view: Parameters<RiffActions["riff.app_view"]>[0];
	ended: Parameters<RiffActions["riff.ended"]>[0];
	pause: Parameters<RiffActions["riff.pause"]>[0];
	play: Parameters<RiffActions["riff.play"]>[0];
	queue: Parameters<RiffActions["riff.queue"]>[0];
	ready: Parameters<RiffActions["riff.ready"]>[0];
	time: Parameters<RiffActions["riff.time"]>[0];
	track: Parameters<RiffActions["riff.track"]>[0];
	view: Parameters<RiffActions["riff.view"]>[0];
}

export type RiffEventMap = {
	[ K in keyof RiffEventDetails as `riff:${ K }` ]: CustomEvent<RiffEventDetails[ K ]>;
};

/** An event's name, such as riff:play. */
export type RiffEvent = keyof RiffEventMap;

// ---- Listen app views.
// A view of the Listen app, as the riff_app_views PHP filter leaves it and Riff\Listen\Views::all() returns it. A plugin adds one in PHP, under a slug of its own, with a label and a render callback; the rest have defaults.

/** A PHP callable: a function's name, or a class or object and a method's name. */
export type PhpCallable = string | [ string | object, string ];

export interface AppView {
	label: string;
	title: string;
	icon: string;
	nav: string[];
	capability: string;
	render: PhpCallable | null;
	script: string[];
	style: string[];
	module: string[];
	own: boolean;
}

/** What a plugin returns from riff_app_views for a view of its own: a label and render, the rest optional. */
export type AppViewDefinition = Pick<AppView, 'label' | 'render'> & Partial<Omit<AppView, 'label' | 'render' | 'own'>>;

/** The views by slug. */
export type AppViews = Record<string, AppView>;

// ---- Globals.
// window.riff once the player starts, and the riff:* events on elements and the document.

declare global {
	interface Window {
		riff?: RiffApi;
	}
	interface HTMLElementEventMap extends RiffEventMap {}
	interface DocumentEventMap extends RiffEventMap {}
}
